import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Easing,
  random,
} from '../remotionShim';
/* -------------------------------------------------------------------------- */
/*                                 FONT LOADER                                */
/* -------------------------------------------------------------------------- */
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@300;400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

/* -------------------------------------------------------------------------- */
/*                                   SCHEMA                                   */
/* -------------------------------------------------------------------------- */


export type CharacterSelectProps = Record<string, any>;

/* -------------------------------------------------------------------------- */
/*                                SUBCOMPONENTS                               */
/* -------------------------------------------------------------------------- */

// Simple abstract female silhouette SVG
const Silhouette: React.FC<{
  color: string;
  opacity: number;
  glow?: string;
  scale?: number;
}> = ({ color, opacity, glow, scale = 1 }) => (
  <div
    style={{
      opacity,
      transform: `scale(${scale})`,
      transition: "none", // Managed by Remotion
      filter: glow ? `drop-shadow(0 0 15px ${glow})` : "none",
    }}
  >
    <svg
      width="100%"
      height="100%"
      viewBox="0 0 100 200"
      preserveAspectRatio="xMidYMid meet"
      style={{ overflow: "visible" }}
    >
      {/* Head */}
      <circle cx="50" cy="40" r="20" fill={color} />
      {/* Neck */}
      <rect x="42" y="55" width="16" height="15" fill={color} />
      {/* Body / Shoulders */}
      <path
        d="M20 80 Q50 60 80 80 L85 200 L15 200 Z"
        fill={color}
      />
    </svg>
  </div>
);

const ParticleSystem: React.FC<{ color: string }> = ({ color }) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const particles = useMemo(() => {
    return new Array(20).fill(0).map((_, i) => ({
      x: random(`x-${i}`) * width,
      y: random(`y-${i}`) * height,
      size: random(`size-${i}`) * 3 + 1,
      speed: random(`speed-${i}`) * 2 + 0.5,
      offset: random(`offset-${i}`) * 100,
    }));
  }, [width, height]);

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {particles.map((p, i) => {
        const yPos = (p.y - frame * p.speed + p.offset) % height;
        const opacity = interpolate(
          Math.sin(frame * 0.05 + p.offset),
          [-1, 1],
          [0.2, 0.6]
        );
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: p.x,
              top: yPos,
              width: p.size,
              height: p.size,
              borderRadius: "50%",
              backgroundColor: color,
              opacity,
              boxShadow: `0 0 ${p.size * 2}px ${color}`,
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

/* -------------------------------------------------------------------------- */
/*                              MAIN COMPONENT                                */
/* -------------------------------------------------------------------------- */
const CharacterSelect: React.FC<CharacterSelectProps> = ({
  backgroundColor = "#F5F0EB",
  transparentBackground = false,
  durationInSeconds = 10,
  accentColor = "#FF6B6B",
  textColor = "#2A2A2A",
  char1Name = "JULIANA",
  char2Name = "THERESE",
  char3Name = "ELLA",
  unlockTitle = "NEW CHARACTER UNLOCKED",
  unlockSubtitle = "now active at glow szn",
}) => {
  // Load Fonts
  useFontLoader(["Outfit", "Manrope"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Color Logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timeline Configuration
  const fadeStart = 0;
  const fadeDuration = 30;
  
  // Selection Timeline
  const highlight1Start = 30; // Juliana
  const highlight2Start = 55; // Therese
  const highlight3Start = 80; // Ella (stops here)
  
  const unlockMoment = 100;
  const textRevealStart = 120;

  // Global Opacity (Fade In)
  const globalOpacity = interpolate(
    frame,
    [fadeStart, fadeStart + fadeDuration],
    [0, 1],
    { extrapolateRight: "clamp" }
  );

  // --- Character Logic ---

  // Cursor Position Logic
  // 0 = None, 1 = Char1, 2 = Char2, 3 = Char3
  // We want to interpolate a "focus" value that travels 1 -> 2 -> 3
  const focusValue = interpolate(
    frame,
    [highlight1Start, highlight2Start, highlight3Start],
    [0, 1, 2],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.quad),
    }
  );

  // Helper to determine state of each character based on focusValue
  const getCharState = (index: number) => {
    // Distance from current focus value (0, 1, 2)
    const distance = Math.abs(focusValue - index);
    
    // Is this the final locked character?
    const isLocked = index === 2 && frame >= unlockMoment;

    // Active Highlight (Scanning)
    const isHighlighted = distance < 0.5 && !isLocked;

    // Base Styles
    let opacity = 0.3; // Inactive / Ghost
    let scale = 1;
    let glow = undefined;

    if (isHighlighted) {
      opacity = interpolate(distance, [0, 0.5], [1, 0.3], { extrapolateRight: "clamp" });
      scale = interpolate(distance, [0, 0.5], [1.05, 1], { extrapolateRight: "clamp" });
    }

    // Unlock Moment Overrides
    if (isLocked) {
      const lockProgress = spring({
        frame: frame - unlockMoment,
        fps,
        config: { damping: 12 },
      });
      
      opacity = 1;
      scale = interpolate(lockProgress, [0, 1], [1.05, 1.2]); // Pop forward
      glow = accentColor;
    } 
    // Fade out others when locked
    else if (frame >= unlockMoment) {
      opacity = interpolate(frame, [unlockMoment, unlockMoment + 20], [0.3, 0.1], { extrapolateRight: "clamp" });
      scale = 1;
    }

    return { opacity, scale, glow };
  };

  const char1State = getCharState(0);
  const char2State = getCharState(1);
  const char3State = getCharState(2);

  // --- UI Elements ---
  
  // Unlock Text Animation
  const unlockTextOpacity = interpolate(
    frame,
    [textRevealStart, textRevealStart + 20],
    [0, 1],
    { extrapolateRight: "clamp" }
  );
  
  const unlockTextY = interpolate(
    frame,
    [textRevealStart, textRevealStart + 30],
    [20, 0],
    { extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
  );

  const subtitleOpacity = interpolate(
    frame,
    [textRevealStart + 20, textRevealStart + 40],
    [0, 0.7],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Outfit, sans-serif",
        color: textColor,
      }}
    >
      {/* Background Ambience */}
      <AbsoluteFill style={{ opacity: 0.05, background: `radial-gradient(circle at 50% 30%, ${accentColor}, transparent 60%)` }} />
      
      {/* Particles (Only prominent after unlock) */}
      {frame > unlockMoment - 20 && (
         <AbsoluteFill style={{ opacity: interpolate(frame, [unlockMoment, unlockMoment + 30], [0, 1]) }}>
            <ParticleSystem color={accentColor} />
         </AbsoluteFill>
      )}

      {/* Main Container */}
      <AbsoluteFill
        style={{
          padding: `${width * 0.05}px`,
          alignItems: "center",
          justifyContent: "center",
          opacity: globalOpacity,
        }}
      >
        {/* Header UI (Fake Game HUD) */}
        <div
          style={{
            position: "absolute",
            top: height * 0.1,
            width: "80%",
            display: "flex",
            justifyContent: "space-between",
            fontSize: width * 0.02,
            opacity: 0.5,
            fontFamily: "Manrope, sans-serif",
            letterSpacing: "0.1em",
            borderBottom: `1px solid ${textColor}33`,
            paddingBottom: 10,
          }}
        >
            <span>SELECT AVATAR</span>
            <span>03 / 03</span>
        </div>

        {/* Characters Container */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "flex-end", // Align feet
            justifyContent: "space-around",
            width: "100%",
            height: height * 0.4,
            marginBottom: height * 0.1,
          }}
        >
          {/* CHAR 1 */}
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 20 }}>
            <div style={{ width: width * 0.2, height: height * 0.3 }}>
               <Silhouette color={textColor} opacity={char1State.opacity} scale={char1State.scale} glow={char1State.glow} />
            </div>
            <span style={{ 
                opacity: char1State.opacity, 
                fontSize: width * 0.03, 
                fontWeight: 600, 
                letterSpacing: "0.05em" 
            }}>
                {char1Name}
            </span>
          </div>

          {/* CHAR 2 */}
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 20 }}>
            <div style={{ width: width * 0.2, height: height * 0.3 }}>
               <Silhouette color={textColor} opacity={char2State.opacity} scale={char2State.scale} glow={char2State.glow} />
            </div>
             <span style={{ 
                opacity: char2State.opacity, 
                fontSize: width * 0.03, 
                fontWeight: 600, 
                letterSpacing: "0.05em" 
            }}>
                {char2Name}
            </span>
          </div>

          {/* CHAR 3 (Target) */}
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 20 }}>
            <div style={{ width: width * 0.2, height: height * 0.3 }}>
               <Silhouette color={textColor} opacity={char3State.opacity} scale={char3State.scale} glow={char3State.glow} />
            </div>
             <span style={{ 
                opacity: char3State.opacity, 
                fontSize: width * 0.03, 
                fontWeight: 600, 
                letterSpacing: "0.05em",
                color: frame > unlockMoment ? accentColor : textColor // Text turns red on unlock
            }}>
                {char3Name}
            </span>
          </div>
        </div>

        {/* Unlock Overlay Text */}
        <div
            style={{
                position: "absolute",
                bottom: height * 0.2,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                textAlign: "center",
                gap: 15,
                transform: `translateY(${unlockTextY}px)`,
                opacity: unlockTextOpacity,
            }}
        >
            <div
                style={{
                    fontFamily: "Manrope, sans-serif",
                    fontSize: width * 0.03,
                    letterSpacing: "0.2em",
                    textTransform: "uppercase",
                    color: accentColor,
                    fontWeight: 700,
                    textShadow: `0 0 10px ${accentColor}66`
                }}
            >
                {unlockTitle}
            </div>
            
            <div
                style={{
                    fontSize: width * 0.12,
                    lineHeight: 0.9,
                    fontWeight: 800,
                    textTransform: "uppercase",
                    letterSpacing: "-0.02em",
                }}
            >
                {char3Name}
            </div>

            <div
                style={{
                    fontFamily: "Manrope, sans-serif",
                    fontSize: width * 0.035,
                    opacity: subtitleOpacity,
                    marginTop: 10,
                    fontStyle: "italic",
                    background: `${textColor}`,
                    color: backgroundColor,
                    padding: "5px 15px",
                    borderRadius: "20px",
                }}
            >
                {unlockSubtitle}
            </div>
        </div>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CharacterSelect;